"""物質2：いろいろな気体とその性質／水溶液の性質（ワーク p60〜75）"""
from fractions import Fraction as F
from kbank import T, C, SEQ, N, S, R
from sci import unit
from matter1 import fs

def kitai():
    u = unit('kitai', '気体の区別と性質', 'いろいろな気体とその性質', {60, 61, 62, 63},
             '2026-10-05 Claude作成。理科ワークp60〜61（教科書チェック①〜⑤・実験3・実験4）・p62基本①②と○×①〜④・p63力だめし①②を写真で確認して作成。物質分野の教科書本文の写真は無いため、ワークの問題とヒント・ポイントを根拠にした。')
    q = u.q
    q(60, '①(1)', 'においのかぎ方', '実験で、気体のにおいはどのようにしてかぐか。', R((1, ['手']), (1, ['あお', '扇', 'あおい', '引き寄せ', 'ひきよせ'])), 'ワークp60①(1)・p62②(1)：手であおぐようにしてかぐ（直接かがない）。', example='手であおぐようにしてかぐ。')
    q(60, '①(2)A', '空気の成分', '空気にふくまれる気体のうち、体積の割合で約78%をしめる気体は何か。', T('窒素', 'ちっそ'), 'ワークp60①(2)：気体A（約78%）＝窒素。', near=['酸素'])
    q(60, '①(2)B', '空気の成分', '空気にふくまれる気体のうち、体積の割合で約21%をしめる気体は何か。', T('酸素', 'さんそ'), 'ワークp60①(2)：気体B（約21%）＝酸素。', near=['窒素', '二酸化炭素'])
    q(60, '①(3)①', '集め方', '水にとけにくい気体を集めるのに適した方法を何というか。', T('水上置換法', 'すいじょうちかんほう'), 'ワークp60①(3)(4)：水にとけにくい→水上置換法。', near=['上方置換法', '下方置換法'])
    q(60, '①(4)b', '集め方', '水にとけやすく、密度が空気よりも小さい気体を集める方法を何というか。', T('上方置換法', 'じょうほうちかんほう'), 'ワークp60①(4)b：上方置換法。', near=['下方置換法'])
    q(60, '①(4)c', '集め方', '水にとけやすく、密度が空気よりも大きい気体を集める方法を何というか。', T('下方置換法', 'かほうちかんほう'), 'ワークp60①(4)c：下方置換法。', near=['上方置換法'])
    q(60, '②(1)', '酸素', '二酸化マンガンにうすい過酸化水素水を加えると発生する気体は何か。', T('酸素', 'さんそ'), 'ワークp60②(1)・p62○×①：酸素。', near=['水素', '二酸化炭素'])
    q(60, '②(2)', '二酸化炭素', '石灰石にうすい塩酸を加えると発生する気体は何か。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp60②(2)：二酸化炭素。', near=['酸素', '水素'])
    q(60, '②(3)', '酸素', '火のついた線香を入れると線香が激しく燃えるのは、酸素と二酸化炭素のどちらか。', T('酸素', 'さんそ'), 'ワークp60②(3)：酸素。', near=['二酸化炭素'])
    q(60, '②(4)', '酸素', '酸素の中で線香が激しく燃えるのは、酸素にどのようなはたらきがあるからか。', R((1, ['燃や', 'もや'])), 'ワークp60②(4)：ものを燃やすはたらきがあるから（酸素そのものは燃えない）。', example='ものを燃やすはたらき')
    q(60, '②(5)', '二酸化炭素', '気体を集めた試験管に石灰水を入れてよく振ると、白くにごるのは酸素と二酸化炭素のどちらか。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp60②(5)：二酸化炭素。', near=['酸素'])
    q(60, '②(6)', '二酸化炭素', '二酸化炭素の水溶液は、青色のリトマス紙を何色に変えるか。', T('赤色', '赤', 'あか', '赤い色'), 'ワークp60②(6)：青色のリトマス紙を赤色に変える→酸性。', near=['青色'])
    q(60, '②(6)', '二酸化炭素', '二酸化炭素の水溶液は、何性を示すか。', T('酸性', 'さんせい'), 'ワークp60②(6)・p62○×②：酸性（アルカリ性は誤り）。', near=['アルカリ性', '中性'])
    q(62, '○×②', '二酸化炭素', '「二酸化炭素は、色やにおいがない気体で、水にとけ、その水溶液はアルカリ性を示す。」この文の誤りを直すと、アルカリ性は何になるか。', T('酸性', 'さんせい'), 'ワークp62○×②：酸性。', near=['アルカリ性'])
    q(60, '②(7)', '二酸化炭素', '二酸化炭素は、水上置換法以外の何という方法でも集めることができるか。', T('下方置換法', 'かほうちかんほう'), 'ワークp60②(7)：下方置換法（空気より密度が大きい）。', near=['上方置換法'])
    q(61, '③(1)', 'アンモニア', '塩化アンモニウムと物質Aを混ぜて加熱し、アンモニアを発生させた。物質Aは何か。', T('水酸化カルシウム', 'すいさんかカルシウム'), 'ワークp61③(1)：水酸化カルシウム。', near=['塩化アンモニウム'])
    q(61, '③(2)', 'アンモニア', 'アンモニアの密度は、空気と比べて大きいか、小さいか。', T('小さい', 'ちいさい'), 'ワークp61③(2)：小さい（上方置換法で集める）。', near=['大きい'])
    q(61, '③(3)', 'アンモニア', 'アンモニアに、水で湿らせた赤色リトマス紙を近づけるとどうなるか。', R((1, ['青', 'あお'])), 'ワークp61③(3)：赤色リトマス紙が青色に変わる。', example='青色に変わる。')
    q(62, '○×③', 'アンモニア', '「アンモニアは上方置換法で集めることができる。」この文は正しいか。正しければ〇、誤りなら正しい言葉を書こう。', T('〇', '○', 'O', 'o', '正しい'), 'ワークp62○×③：○。', near=['下方置換法', '水上置換法'])
    q(61, '③(4)', 'アンモニア', 'アンモニアを満たしたフラスコにスポイトで水を入れると、ビーカーの水がフラスコ内に勢いよく上がって噴水となる。その理由を書こう。', R((1, ['とけ', '溶け']), (1, ['やす', '多く', 'たくさん', '非常'])), 'ワークp61③(4)：アンモニアが水に非常にとけやすく、フラスコ内の気体の体積が減るから。', example='アンモニアが水に非常にとけやすいから。')
    q(61, '③(5)', 'アンモニア', '噴水の実験で、フェノールフタレイン溶液を加えた水が赤色になったことから、アンモニアがとけた水溶液は何性を示すとわかるか。', T('アルカリ性', 'あるかりせい'), 'ワークp61③(5)：アルカリ性。', near=['酸性', '中性'])
    q(63, '②(5)', 'アンモニア', 'アンモニアを水上置換法で集めることができない理由を簡潔に書こう。', R((1, ['水']), (1, ['とけ', '溶け']), (1, ['やす', '非常', '多く'])), 'ワークp63②(5)：アンモニアは水に非常にとけやすいから。', example='水に非常にとけやすいから。')
    q(61, '④(1)', '水素', '水素を発生させるとき、亜鉛（B）に加えるもの（A）は何か。', T('うすい塩酸', '塩酸', 'えんさん'), 'ワークp61④(1)・p62①(2)：A うすい塩酸、B 亜鉛。', near=['過酸化水素水'])
    q(61, '④(2)', '水素', '集めた水素に火を近づけると、水素はどうなるか。', R((1, ['音']), (1, ['燃え', 'もえ'])), 'ワークp61④(2)・p62①(4)①：音を立てて燃える。', example='音を立てて燃える。')
    q(61, '④(3)', '水素', '水素が燃えると、何という物質ができるか。', T('水', 'みず'), 'ワークp61④(3)：水。', near=['二酸化炭素'])
    q(61, '④(4)', '水素', '水素は、物質の中で密度がいちばん大きいか、小さいか。', T('小さい', 'ちいさい'), 'ワークp61④(4)・p62○×④：小さい。', near=['大きい'])
    q(62, '○×④', '水素', '「水素は、物質の中で密度がいちばん大きい。」この文の誤りを直すと、「大きい」は何になるか。', T('小さい', 'ちいさい'), 'ワークp62○×④：小さい。', near=['大きい'])
    q(61, '④(5)', '窒素', '窒素には、色やにおいがあるか。', T('ない', 'なし', 'ありません', 'どちらもない'), 'ワークp61④(5)：ない。', near=['ある'])
    q(61, '⑤(1)A', '身のまわりの気体', '発泡入浴剤に約60℃の湯を加えると発生する気体は何か。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp61⑤(1)A：二酸化炭素。', near=['酸素'])
    q(61, '⑤(1)B', '身のまわりの気体', '風呂がま洗浄剤に約60℃の湯を加えると発生する気体は何か。', T('酸素', 'さんそ'), 'ワークp61⑤(1)B：酸素。', near=['二酸化炭素'])
    q(61, '⑤(1)C', '身のまわりの気体', '卵の殻に食酢を加えると発生する気体は何か。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp61⑤(1)C：二酸化炭素（卵の殻は石灰石と同じ炭酸カルシウム）。', near=['酸素', '水素'])
    q(61, '⑤(1)D', '身のまわりの気体', 'ダイコンおろしにオキシドール（うすい過酸化水素水）を加えると発生する気体は何か。', T('酸素', 'さんそ'), 'ワークp61⑤(1)D：酸素。', near=['水素'])
    q(61, '⑤(2)①', '身のまわりの気体', '発泡入浴剤・風呂がま洗浄剤・卵の殻と食酢・ダイコンおろしとオキシドールのうち、火のついた線香を激しく燃やす気体が発生するものを2つ答えよう。', S(('風呂がま洗浄剤', '風呂がま洗浄剤に湯', '風呂釜洗浄剤'), ('ダイコンおろし', 'ダイコンおろしとオキシドール', '大根おろし')), 'ワークp61⑤(2)①：B・D（酸素）。', near=['風呂がま洗浄剤'])
    q(61, '⑤(2)②', '身のまわりの気体', '発泡入浴剤・風呂がま洗浄剤・卵の殻と食酢・ダイコンおろしとオキシドールのうち、石灰水を白くにごらせる気体が発生するものを2つ答えよう。', S(('発泡入浴剤', '発泡入浴剤に湯', '入浴剤'), ('卵の殻', '卵の殻と食酢', 'たまごのから')), 'ワークp61⑤(2)②：A・C（二酸化炭素）。', near=['発泡入浴剤'])
    q(62, '①(4)②', '気体の区別', '火のついた線香を入れると、線香が激しく燃える気体は、酸素・二酸化炭素・水素のどれか。', T('酸素', 'さんそ'), 'ワークp62①(4)②：酸素。', near=['水素'])
    q(62, '①(4)③', '気体の区別', '石灰水を入れてよく振ると白くにごる気体は、酸素・二酸化炭素・水素のどれか。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp62①(4)③：二酸化炭素。', near=['酸素'])
    q(62, '②(2)', '刺激臭', 'アンモニア・窒素・二酸化炭素のうち、刺激臭があるのはどれか。', T('アンモニア', 'あんもにあ'), 'ワークp62②(2)：アンモニア。', near=['窒素'])
    q(62, '②(3)', '水へのとけやすさ', 'アンモニア・窒素・二酸化炭素を入れたペットボトルに水を入れて振ったとき、水にとけにくかったのはどれか。', T('窒素', 'ちっそ'), 'ワークp62②(3)：窒素（ペットボトルがへこまない）。', near=['二酸化炭素', 'アンモニア'])
    q(62, '②(4)①', 'BTB溶液', '緑色のBTB溶液を加えると黄色に変化したのは、アンモニア・窒素・二酸化炭素のどれをとかした水か。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp62②(4)①：黄色＝酸性＝二酸化炭素。', near=['アンモニア'])
    q(62, '②(4)②', 'BTB溶液', '緑色のBTB溶液を加えると青色に変化したのは、アンモニア・窒素・二酸化炭素のどれをとかした水か。', T('アンモニア', 'あんもにあ'), 'ワークp62②(4)②：青色＝アルカリ性＝アンモニア。', near=['二酸化炭素'])
    q(62, '②(4)', 'BTB溶液', 'BTB溶液は、酸性で何色、中性で何色、アルカリ性で何色になるか。この順に書こう。', SEQ(['黄色', '緑色', '青色'], seps=('、', '・', ',', ' ', '→')), 'ワークp62②(4)：緑色のBTB溶液が、二酸化炭素（酸性）で黄色、アンモニア（アルカリ性）で青色。中性は緑色のまま。', near=['青色、緑色、黄色'])
    q(63, '①(1)', '酸素の発生', '固体Xにうすい過酸化水素水を加えて酸素を発生させた。固体Xは、二酸化マンガン・亜鉛・石灰石のどれか。', T('二酸化マンガン', 'にさんかマンガン'), 'ワークp63①(1)：ア 二酸化マンガン。', near=['亜鉛', '石灰石'])
    q(63, '①(3)', '酸素の集め方', '酸素の集め方として水上置換法が最適なのは、酸素がどのような性質をもっているからか。', R((1, ['水']), (1, ['とけにく', '溶けにく', 'とけな', '溶けな'])), 'ワークp63①(3)：酸素は水にとけにくい性質をもっているから。', example='水にとけにくい性質')
    q(63, '①(4)', '酸素の集め方', '酸素を集める実験で、最初に集めた試験管の気体を捨てるのはなぜか。', R((1, ['空気', 'くうき'])), 'ワークp63①(4)ヒント：実験前の実験装置の中には空気が入っている。最初に出てくる気体には装置内の空気が多くふくまれるから。', example='装置の中にあった空気が多くふくまれているから。')
    q(63, '①(5)', '酸素の性質', '酸素の性質について正しいものを、次からすべて選ぼう。\nア 石灰水を白くにごらせる　イ 気体そのものが燃える　ウ ものを燃やすはたらきがある　エ 空気中に体積の割合で約21%ふくまれている　オ 物質の中でいちばん密度が小さい', C('ウエ'), 'ワークp63①(5)：ウ・エ。酸素そのものは燃えない（ヒント）。密度がいちばん小さいのは水素。', near=['ウ', 'エ'])
    q(63, '②(1)', '気体の表', '水へのとけ方が「少しとける」、空気を1としたときの密度の比が1.53の気体は、窒素・水素・アンモニア・二酸化炭素のどれか。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp63②の表A：少しとける・1.53＝二酸化炭素。', near=['窒素'])
    q(63, '②(2)', '気体の表', '水へのとけ方が「とけにくい」、密度の比が0.97の気体は、空気中に体積の割合で約78%ふくまれる。何か。', T('窒素', 'ちっそ'), 'ワークp63②の表C：0.97＝窒素。', near=['水素', '酸素'])
    q(63, '②(3)', '気体の表', '水へのとけ方が「とけにくい」、密度の比が0.07の気体は、窒素・水素・アンモニア・二酸化炭素のどれか。', T('水素', 'すいそ'), 'ワークp63②の表B：0.07＝水素（同じ体積で比べたとき最も質量が小さい）。', near=['窒素'])
    q(63, '②(6)', '気体の表', '水へのとけ方が「非常にとけやすい」、密度の比が0.60の気体は、窒素・水素・アンモニア・二酸化炭素のどれか。', T('アンモニア', 'あんもにあ'), 'ワークp63②の表D：0.60＝アンモニア（上方置換法で集める）。', near=['水素'])
    q(63, '②(6)', '集め方と密度', '空気を1としたときの密度の比が1より大きく、水に少しとける気体は、上方置換法と下方置換法のどちらでも集められるか。', T('下方置換法', 'かほうちかんほう'), 'ワークp63②(6)ヒント：密度に着目。空気より密度が大きい→下方置換法。', near=['上方置換法'])
    q(63, '②(4)', '集め方', '水を満たした試験管を水そうに立て、気体を入れて水と置きかえて集める方法を何というか。', T('水上置換法', 'すいじょうちかんほう'), 'ワークp63②(4)：アの方法＝水上置換法。', near=['上方置換法'])
    q(60, '実験3', '気体の発生', '酸素や二酸化炭素を水上置換法で集めるとき、三角フラスコからのびた何の先を水そうの試験管に入れるか。', T('ゴム管', 'ガラス管', 'ごむかん', 'ガラス管（ゴム管）'), 'ワークp60実験3の図：三角フラスコ→ゴム栓→ゴム管（ガラス管）→水を満たした試験管。')
    q(60, '①(3)②', '集め方', '空気よりも密度が小さく水にとけやすい気体は、試験管の口をどちらに向けて集めるか。', T('下', 'した', '下向き'), 'ワークp60①(4)bの写真：上方置換法は試験管の口を下に向けて集める（軽い気体が上にたまる）。', near=['上'])
    q(60, '①(3)②', '集め方', '空気よりも密度が大きく水にとけやすい気体は、試験管の口をどちらに向けて集めるか。', T('上', 'うえ', '上向き'), 'ワークp60①(4)cの写真：下方置換法は試験管の口を上に向けて集める。', near=['下'])
    for gas, how, ng in [('酸素', '水上置換法', '上方置換法'), ('水素', '水上置換法', '下方置換法'), ('アンモニア', '上方置換法', '水上置換法'), ('窒素', '水上置換法', '上方置換法')]:
        q(60, '①(4)', '集め方', f'{gas}を集めるのに最も適した方法は何か。', T(how), f'ワークp60①・p63②：水にとけにくい気体は水上置換法。水にとけやすく空気より軽いアンモニアは上方置換法。{gas}→{how}。', near=[ng])
    q(62, '①(4)①', '気体の区別', '空気中で火をつけると音を立てて燃えるのは、酸素・二酸化炭素・水素のどれか。', T('水素', 'すいそ'), 'ワークp62①(4)①：水素。', near=['酸素'])
