    q(70, '①(2)', '溶ける量の限度', '一定量の水にとける物質の量に、限度はあるか。', T('ある', 'あります', '限度がある'), 'ワークp70①(2)：ある（とけきれなくなり固体のまま残った）。', near=['ない'])
