    q(70, '①(4)', '飽和水溶液', '物質が限度までとけている水溶液を何というか。', T('飽和水溶液', 'ほうわすいようえき'), 'ワークp70①(4)・p74②(1)：飽和水溶液。', near=['水溶液'])
    q(70, '①(5)', '溶解度', '水100 gに物質をとかして飽和水溶液にしたとき、とけた溶質の質量〔g〕の値を、その物質の何というか。', T('溶解度', 'ようかいど'), 'ワークp70①(5)・p74○×③：溶解度。', near=['質量パーセント濃度'])
    q(70, '①(6)', '溶解度曲線', '溶解度と温度の関係を表したグラフを何というか。', T('溶解度曲線', 'ようかいどきょくせん'), 'ワークp70①(6)・p74②(2)：溶解度曲線。', near=['溶解度'])
    q(70, '①(1)', '溶ける量', '塩化ナトリウム20 gとミョウバン20 gを、それぞれ50 gの水に少しずつとかすと、はじめは水溶液の見た目はどうなっているか。', R((1, ['透明', 'とうめい', 'すきとお'])), 'ワークp70①(1)：はじめは透明になっている（全部とけている）。', example='透明になっている。')
    q(70, '①(7)①', '溶解度曲線', 'ワークの溶解度曲線で、20℃の水100 gにとける質量が多いのは、塩化ナトリウムと硝酸カリウムのどちらか。', T('塩化ナトリウム', 'えんかナトリウム'), 'ワークp70①(7)①：20℃では塩化ナトリウム（約36 g）のほうが硝酸カリウム（約32 g）より多い。', near=['硝酸カリウム'])
    q(70, '①(7)②', '溶解度曲線', '同じグラフで、40℃の水100 gにとける質量が多いのは、塩化ナトリウムと硝酸カリウムのどちらか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp70①(7)②・p72要点の例：40℃の硝酸カリウムの溶解度は約64 gで、塩化ナトリウムより多い。', near=['塩化ナトリウム'])
    q(72, '①', '溶解度の読みとり', '溶解度曲線から溶解度を読みとるとき、横軸で何を読み、曲線と交わったところで縦軸の何を読むか。', R((1, ['温度', 'おんど']), (1, ['質量', '溶解度', 'とける'])), 'ワークp72①こう解く：横軸で温度を読み、上にたどって曲線と交わったところで、縦軸の値（水100 gにとける物質の質量）を読む。', example='横軸で温度を読み、縦軸でとける質量を読む。')
    q(72, '①例', '溶解度の読みとり', 'ワークの例で、40℃における硝酸カリウムの溶解度は約何gか。', N(64, ['g']), 'ワークp72①例：40℃における硝酸カリウムの溶解度は約64 g。', near=['40', '46'])
    q(70, '①(8)', '溶解度', '20℃の水100 gに塩化ナトリウムとミョウバンをそれぞれ40 g加えたとき、とけ残りが多いのはどちらか。', T('ミョウバン', 'みょうばん'), 'ワークp70①(8)：20℃のミョウバンの溶解度（11.4 g）は塩化ナトリウム（約36 g）よりずっと小さいので、ミョウバンのとけ残りが多い。', near=['塩化ナトリウム'])
    q(70, '①(9)', '溶解度', '20℃の水100 gに塩化ナトリウムとミョウバンをそれぞれ40 g加えた液を60℃にあたためた。すべてとけるのはどちらか。', T('ミョウバン', 'みょうばん'), 'ワークp70①(9)：60℃のミョウバンの溶解度は57.4 gで40 gより大きいのでとける。塩化ナトリウムは温度でほとんど変わらず約37 gなのでとけ残る。', near=['塩化ナトリウム'])
    q(71, '③(3)', '溶解度の特徴', '水溶液を冷やしたとき、とけていた溶質の固体がほとんど出てこないのは、温度によって溶解度がどうなる物質か。', R((1, ['ほとんど', 'あまり']), (1, ['変化', '変わら', 'かわら'])), 'ワークp71③(3)イ：温度による溶解度の変化がほとんどない（塩化ナトリウム）。', example='温度による溶解度の変化がほとんどない物質')
    q(71, '③(2)', '実験5', '実験5で、50℃の水5 cm³に塩化ナトリウムと硝酸カリウムをそれぞれ3 gとかしたあと、20℃まで下げた。現れた溶質の固体が多かったのはどちらか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp71③(2)：硝酸カリウム（温度によって溶解度が大きくちがう）。', near=['塩化ナトリウム'])
    q(71, '③(4)', '溶質のとり出し方', '塩化ナトリウム水溶液から塩化ナトリウムをとり出すのに適している方法を書こう。', R((1, ['蒸発', 'じょうはつ', '加熱', 'かねつ'])), 'ワークp71③(4)キーワード「蒸発」：水を蒸発させる（塩化ナトリウムは冷やしてもほとんど出てこない）。', example='水を蒸発させる。')
    q(75, '②(6)', '溶質のとり出し方', '冷やしても結晶がほとんど出てこなかった水溶液から結晶をとり出す方法を書こう。', R((1, ['蒸発', 'じょうはつ', '加熱', '水を減ら'])), 'ワークp75②(6)：水を蒸発させる。', example='水溶液を加熱して水を蒸発させる。')
    q(71, '③(6)', '結晶', '純粋な物質で、規則正しい形をした固体を何というか。', T('結晶', 'けっしょう'), 'ワークp71③(6)：結晶。', near=['溶質'])
    q(71, '③(7)', '再結晶', '物質をいったん水などの溶媒にとかし、温度を下げたり溶媒を蒸発させたりして再び結晶としてとり出す操作を何というか。', T('再結晶', 'さいけっしょう'), 'ワークp71③(7)・p74②(4)：再結晶。', near=['ろ過', '蒸留'])
    q(71, '③(5)', '結晶の形', '立方体のような形の結晶ができるのは、塩化ナトリウムと硝酸カリウムのどちらか。', T('塩化ナトリウム', 'えんかナトリウム'), 'ワークp71③(5)b・p74②(5)：塩化ナトリウムの結晶は立方体のような形（ウ）。硝酸カリウムは細長い針状（a）。', near=['硝酸カリウム'])
    q(71, '③(5)', '結晶の形', '細長い棒（針）のような形の結晶ができるのは、塩化ナトリウムと硝酸カリウムのどちらか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp71③(5)a：硝酸カリウム。', near=['塩化ナトリウム'])
    q(71, '④(1)', '混合物', '複数の物質が混ざり合ったものを何というか。', T('混合物', 'こんごうぶつ'), 'ワークp71④(1)：混合物。', near=['純物質'])
    q(71, '④(2)', '純物質', '1種類の物質でできているものを何というか。', T('純物質', 'じゅんぶっしつ', '純粋な物質'), 'ワークp71④(2)：純物質。', near=['混合物'])
    q(71, '④(3)', '混合物と純物質', '水・空気・酸素・炭酸水のうち、混合物をすべて答えよう。', S(('空気', 'くうき'), ('炭酸水', 'たんさんすい')), 'ワークp71④(3)：混合物＝空気・炭酸水、純物質＝水・酸素。', near=['空気'])
    q(71, '④(3)', '混合物と純物質', '水・空気・酸素・炭酸水のうち、純物質をすべて答えよう。', S(('水', 'みず'), ('酸素', 'さんそ')), 'ワークp71④(3)：純物質＝水・酸素。', near=['水'])
    q(74, '○×④', '混合物', '「空気や水溶液は純物質である。」この文の誤りを直すと、純物質は何になるか。', T('混合物', 'こんごうぶつ'), 'ワークp74○×④：混合物。', near=['純物質'])
    q(71, '④(4)', '再結晶の利用', '再結晶を利用するとどのようなことができるか。次から選ぼう。\nア 混合物から、より純粋な物質（結晶）を分離できる　イ いくつかの種類の物質が均一に混ざった結晶が得られる', T('ア'), 'ワークp71④(4)：ア。', near=['イ'])
    q(70, '②(1)', 'ろ過', 'ろ過では、ろ紙の穴よりも大きい粒子と小さい粒子のどちらがろ紙を通りぬけるか。', T('小さい粒子', '小さい', 'ちいさい粒子'), 'ワークp70②(1)：小さい粒子。', near=['大きい粒子'])
    q(70, '②(2)', 'ろ過', 'ろ紙をろうとにのせてから、ろうとに密着させるために、ろ紙にどのようなことをするか。', R((1, ['水']), (1, ['ぬら', '濡ら', 'しめら', '湿ら'])), 'ワークp70②(2)：ろ紙を水でぬらす。', example='水でぬらす。')
    q(70, '②(3)', 'ろ過', 'ろ過するとき、液は何を伝わらせて入れるか。', T('ガラス棒', 'がらすぼう'), 'ワークp70②(3)：ガラス棒。', near=['ろうと'])
    q(70, '②(4)', 'ろ過', 'ろ過するとき、ろうとのあしの先はどのようにしておくか。', R((1, ['長い', 'とがった', '切り口', 'きりくち']), (1, ['ビーカー', 'かべ', '壁', '内側', 'つけ'])), 'ワークp70②(4)キーワード「ろうとのあしの切り口」：ろうとのあしのとがった（長い）ほうをビーカーのかべにつける。', example='ろうとのあしの長いほうをビーカーのかべにつける。')
    q(74, '②(3)', '再結晶', '硝酸カリウム・塩化ナトリウム・ミョウバンをそれぞれ40℃の水100 gにとけるだけとかし、20℃まで冷やした。出てくる結晶の質量がもっとも大きいのはどれか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp74②(3)ヒント：40℃と20℃のときの溶解度の差が、出てくる結晶の質量。硝酸カリウムの差がいちばん大きい。', near=['ミョウバン', '塩化ナトリウム'])
    q(75, '②(1)', '溶解度曲線', 'ワークp75の物質Aは温度が上がると溶解度が大きくふえ、物質Bはほとんど変わらない。10℃の水100 gに多くとけるのは、Bのほうである。60℃から10℃まで冷やしたときに結晶が多く出てくるのはどちらか。', T('A', '物質A'), 'ワークp75②(2)：温度による溶解度の変化が大きいAの水溶液から、結晶が多く出てくる。', near=['B'])
    q(75, '②(3)', '再結晶', '水溶液から出てきた結晶をとり出すためには、何という操作をすればよいか。', T('ろ過', 'ろか', '濾過'), 'ワークp75②(3)：ろ過。', near=['再結晶'])
    q(75, '②(5)', '溶解度', 'もう一方の水溶液から結晶がほとんど出てこなかった理由を簡潔に書こう。', R((1, ['溶解度']), (1, ['温度']), (1, ['ほとんど', 'あまり', '小さ']), (1, ['変', 'かわ'])), 'ワークp75②(5)：物質Bは温度による溶解度の変化がほとんどないから。', example='温度による溶解度の変化がほとんどないから。')
    # 溶解度の計算（ワークp72〜73に示された溶解度の値を使う）
    SOL = [('ミョウバン', 20, '11.4'), ('ミョウバン', 60, '57.4'), ('硝酸カリウム', 60, '109.2'), ('ショ糖', 20, '203.9'), ('ショ糖', 0, '179.2'), ('ホウ酸', 20, '4.9')]
    for name, t, sd in SOL:
        for water in ([200, 250] if name == 'ミョウバン' and t == 20 else [50, 300] if name != 'ショ糖' else [100, 50]):
            mx = F(sd) * water / 100
            q(72, '②', 'とかすことのできる最大の量', f'{t}℃の水{water} gに、{name}は最大で何gまでとかすことができるか。ただし、{t}℃における{name}の溶解度は{sd} gとする。', N(fs(mx), ['g']), f'とかすことのできる最大の量＝溶解度×水の質量÷100＝{sd}×{water}÷100＝{fs(mx)} g（ワークp72②こう解く）。', near=[sd] if fs(mx) != sd else [])
    for name, t, sd, water, put in [('ショ糖', 20, '203.9', 100, 90), ('ミョウバン', 60, '57.4', 250, 90), ('ミョウバン', 20, '11.4', 200, 10), ('硝酸カリウム', 60, '109.2', 50, 30)]:
        rest = F(sd) * water / 100 - put
        q(73, '③', 'まだとかすことのできる量', f'{t}℃の水{water} gに{name}{put} gをとかした。{name}はあと何gとかすことができるか。ただし、{t}℃における{name}の溶解度は{sd} gとする。', N(fs(rest), ['g']), f'最大量＝{sd}×{water}÷100＝{fs(F(sd) * water / 100)} g。とかすことのできる量＝{fs(F(sd) * water / 100)}−{put}＝{fs(rest)} g（ワークp73③）。', near=[fs(F(sd) - put)] if F(sd) - put > 0 and F(sd) - put != rest else [])
    for name, t1, t2, sd2, water, put in [('ショ糖', 80, 0, '179.2', 100, 300), ('ホウ酸', 60, 20, '4.9', 300, 40), ('ミョウバン', 60, 20, '11.4', 200, 50), ('ミョウバン', 60, 20, '11.4', 100, 50)]:
        out = put - F(sd2) * water / 100
        q(73, '④', '出てくる結晶の量', f'{t1}℃の水{water} gに{name}{put} gを完全にとかした後、{t2}℃まで冷やした。結晶は何g出てくるか。ただし、{t2}℃における{name}の溶解度は{sd2} gとする。', N(fs(out), ['g']), f'冷やした水にとかすことのできる最大の量＝{sd2}×{water}÷100＝{fs(F(sd2) * water / 100)} g。出てくる結晶＝{put}−{fs(F(sd2) * water / 100)}＝{fs(out)} g（ワークp73④）。', near=[fs(put - F(sd2))] if put - F(sd2) != out and put - F(sd2) > 0 else [])
    q(71, 'ココに注目', '溶解度と水の量', '実験5では、水5 cm³（5.0 g）に溶質を3 gずつ入れた。これは、水100 gでは何gずつ入れたことになるか。', N(60, ['g']), 'ワークp71ココに注目：100÷5＝20（倍）なので、3×20＝60 gずつ入れたことになる。', near=['15', '3'])
    q(72, '①', '溶解度の読みとり', '溶解度は、何gの水にとける物質の質量で表すか。', N(100, ['g']), 'ワークp70①(5)・p72：溶解度は水100 gにとかして飽和水溶液にしたときの溶質の質量。', near=['1000', '1'])
    for water in (100, 50, 150, 300):
        out = (F('57.4') - F('11.4')) * water / 100
        q(73, '④', '出てくる結晶の量', f'60℃の水{water} gにミョウバンをとけるだけとかして飽和水溶液をつくり、20℃まで冷やした。結晶は何g出てくるか。ただし、ミョウバンの溶解度は60℃で57.4 g、20℃で11.4 gとする。', N(fs(out), ['g']), f'水100 gあたり57.4−11.4＝46 g出てくる。水{water} gでは46×{water}÷100＝{fs(out)} g（ワークp74②(3)ヒント：溶解度の差が出てくる結晶の質量）。', near=['46'] if water != 100 else ['57.4', '11.4'])
    for name, t, sd in [('ミョウバン', 60, '57.4'), ('硝酸カリウム', 60, '109.2'), ('ホウ酸', 20, '4.9'), ('ショ糖', 20, '203.9')]:
        c = F(sd) * 100 / (100 + F(sd))
        r = int(c + F(1, 2))
        q(72, '②', '飽和水溶液の濃度', f'{t}℃における{name}の飽和水溶液の質量パーセント濃度は何%か。小数第1位を四捨五入して整数で答えよう。ただし、{t}℃における{name}の溶解度は{sd} gとする。', N(r, ['%', '％']), f'水100 gに{sd} gとけているので、溶液は{fs(100 + F(sd))} g。{sd}÷{fs(100 + F(sd))}×100＝{float(c):.2f}…≒{r}%（質量パーセント濃度の式はワークp65）。', near=[str(int(F(sd) + F(1, 2)))] if int(F(sd) + F(1, 2)) != r else [])
    q(71, '③(3)', '温度と溶解度', '水溶液の温度を下げることで結晶を多くとり出すのに適しているのは、塩化ナトリウムと硝酸カリウムのどちらか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp71③：硝酸カリウムは温度によって溶解度が大きくちがうので、冷やすと結晶が多く出る。', near=['塩化ナトリウム'])
    q(70, '①(6)', '溶解度曲線', '硝酸カリウムやミョウバンの溶解度は、温度が高くなるとどうなるか。', T('大きくなる', 'ふえる', '増える', '大きい'), 'ワークp70①図2・p72：硝酸カリウムやミョウバンの溶解度曲線は、温度が高いほど大きくなる。', near=['小さくなる'])
    q(70, '①(6)', '溶解度曲線', '塩化ナトリウムの溶解度は、温度が変わるとどうなるか。', R((1, ['ほとんど', 'あまり']), (1, ['変わら', 'かわら', '変化しな', '同じ'])), 'ワークp70①図2・p71③(3)：塩化ナトリウムは温度による溶解度の変化がほとんどない。', example='ほとんど変わらない。')
    q(71, '③(1)', '実験5', '実験5で、50℃の水5 cm³に塩化ナトリウムと硝酸カリウムをそれぞれ3 gとかしたとき、全部とけたのはどちらか。', T('硝酸カリウム', 'しょうさんカリウム'), 'ワークp71③(1)・ココに注目：水100 gあたり60 g入れたことになる。50℃の硝酸カリウムの溶解度は60 gより大きいのでとけ、塩化ナトリウム（約37 g）はとけ残る。', near=['塩化ナトリウム'])
    q(72, '①', '溶解度の読みとり', 'ワークp72の溶解度曲線で、溶解度が温度によってほとんど変わらず、どの温度でも約40 g以下のものは、硝酸カリウムと塩化ナトリウムのどちらか。', T('塩化ナトリウム', 'えんかナトリウム'), 'ワークp72①のグラフ：塩化ナトリウムはほぼ水平な線。', near=['硝酸カリウム'])
    q(73, '④', '出てくる結晶の量', '出てくる結晶の量を求める式を、「最初にとかした量」「冷やした水にとかすことのできる最大の量」という言葉を使って書こう。', R((1, ['最初']), (1, ['最大']), (1, ['-', '−', 'ひく', '引く', '－'])), 'ワークp73④こう解く：出てくる結晶の量〔g〕＝最初にとかした量〔g〕−冷やした水にとかすことのできる最大の量〔g〕。', example='最初にとかした量−冷やした水にとかすことのできる最大の量')
    return u
